  "relations": [
    {
      "from": "market",
      "to": "checkout_session",
      "from_cardinality": "1",
      "to_cardinality": "N",
      "meaning": "确定交易站点"
    },
    {
      "from": "market",
      "to": "market_acquiring_route",
      "from_cardinality": "1",
      "to_cardinality": "N",
      "meaning": "配置可用支付方式"
    },
    {
      "from": "payment_method",
      "to": "market_acquiring_route",
      "from_cardinality": "1",
      "to_cardinality": "N",
      "meaning": "被路由引用"
    },
    {
      "from": "sales_channel",
      "to": "checkout_session",
      "from_cardinality": "1",
      "to_cardinality": "N",
      "meaning": "确定交易渠道"
    },
    {
      "from": "checkout_session",
      "to": "parent_order",
      "from_cardinality": "1",
      "to_cardinality": "0..1",
      "meaning": "继承并冻结"
    },
    {
      "from": "parent_order",
      "to": "order",
      "from_cardinality": "1",
      "to_cardinality": "N",
      "meaning": "支付成功后拆分"
    },
    {
      "from": "parent_order",
      "to": "payment_order",
      "from_cardinality": "1",
      "to_cardinality": "1",
      "meaning": "创建支付单"
    },
    {
      "from": "market_acquiring_route",
      "to": "payment_order",
      "from_cardinality": "1",
      "to_cardinality": "N",
      "meaning": "下单时选用并快照"
    },
    {
      "from": "payment_order",
      "to": "refund_order",
      "from_cardinality": "1",
      "to_cardinality": "N",
      "meaning": "原路退款"
    }
  ],
  "rules": [
    "US 固定 USD；HK 固定 HKD；同一结算、订单、支付与退款只允许一个币种。",
    "父订单创建后 market_id、country_code、channel_id、currency_code 不可修改。",
    "支付请求和回调金额、币种必须与 payment_order 一致；不一致时不确认到账。",
    "refund_order 只从原 payment_order 继承通道、商户账号与币种，不读取用户当前 Market。",
    "关闭香港新结算不影响历史香港订单查单、履约和退款。",
    "支付方式为全局主数据，method_code 唯一；产品后台只维护支付通道，商户账号与凭证由技术侧支付接入配置维护。",
    "收单路由 market_id + payment_method_id 唯一；US 启用 PayPal、Credit Card、Apple Pay、Klarna，HK 启用前三种且不配置 Klarna。",
    "主数据停用时关联路由同步停用；payment_order 保留路由引用并快照方式、通道、账号与币种。"
  ]
}
